Q=[]; H={}
for n,(who,series,career,steps) in C.items():
    amt=[("discover",12),("understand",5),("present",1)]
    rew=[(1200,15,100,160),(2000,25,160,260)]
    prev=f"pr_{n}_4"
    for i,(nm,hook,end) in enumerate(steps,1):
        k,a=amt[i-1]
        c,f,x=(1200,15,100) if i==1 else (2000,25,170) if i==2 else (3500,45,280)
        Q.append(dict(id=f"sc_{n}_{i}",name=nm,summary=f"학자의 길 · {who} — "+{"discover":f"도감 카드 {a}장 발견","understand":f"지식 {a}개 이해하기","present":"학회에서 연구 발표 1번 하기"}[k],kind=k,amount=a,nation=n,strand="main",rewardCoins=c,rewardFame=f,rewardCareer=career,rewardXp=x,after=prev))
        H[f"sc_{n}_{i}"]=(hook,end); prev=f"sc_{n}_{i}"
def lua(s): 
    assert ']==]' not in s; return '[==[%s]==]'%s
