for q in Q:
    f=lambda v: lua(v) if isinstance(v,str) else str(v)
    o.append('table.insert(Q, { %s })'%', '.join('%s = %s'%(k,('"%s"'%v if k not in('name','summary') else lua(v)) if isinstance(v,str) else v) for k,v in q.items()))
    o.append('HAND["%s"] = { %s, %s }'%(q['id'],lua(H[q['id']][0]),lua(H[q['id']][1])))
o.append('return { Quests = Q, Hand = HAND }')
